import{_ as a,o as n,c as s,a2 as o}from"./chunks/framework.BxL9yGGP.js";const h=JSON.parse('{"title":"Authentication","description":"","frontmatter":{},"headers":[],"relativePath":"authentication.md","filePath":"authentication.md","lastUpdated":null}'),t={name:"authentication.md"};function i(r,e,l,c,d,p){return n(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h1><p>Homelab Console supports two explicit human-login modes. <code>password</code> (the default) uses username + password followed by a Telegram-delivered second factor. <code>telegram_only</code> uses the username only to identify the account and requires Telegram approval or the Telegram-delivered OTP as the sole factor. Auth never depends on Home Assistant or any infrastructure provider. The API and database currently run on the home application host, so login remains available during an individual provider or Sentinel WireGuard outage but not during a complete home application host/home-site outage. Recovery codes keep web login independent of Telegram availability.</p><h2 id="login-modes" tabindex="-1">Login modes <a class="header-anchor" href="#login-modes" aria-label="Permalink to &quot;Login modes&quot;">​</a></h2><p><code>AUTH_LOGIN_MODE=password</code> is the secure default:</p><ul><li>Passwords are hashed with <strong>Argon2id</strong>. Plaintext passwords are never stored or logged.</li><li>Failed attempts are rate-limited per account and per IP (see <a href="#rate-limiting">Rate limiting</a>).</li><li>On success, the server creates a <strong>login challenge</strong> rather than a session — the second factor is still required.</li></ul><p><code>AUTH_LOGIN_MODE=telegram_only</code> is an explicit single-factor operator mode:</p><ul><li>the login request accepts a username and rejects a password field;</li><li>an active matching account may create a short-lived Telegram challenge;</li><li>possession of the allowed Telegram identity is the only authentication factor, so the bot token, numeric user/chat IDs and webhook secret become critical authentication material;</li><li>password recovery codes are unavailable; direct database access is the recovery path if Telegram is lost;</li><li>existing password hashes remain stored so rollback to <code>password</code> mode does not require an account migration.</li></ul><h2 id="second-factor-telegram-approval-or-otp" tabindex="-1">Second factor: Telegram approval or OTP <a class="header-anchor" href="#second-factor-telegram-approval-or-otp" aria-label="Permalink to &quot;Second factor: Telegram approval or OTP&quot;">​</a></h2><p>Two delivery modes for the second factor:</p><ol><li><strong>Telegram approval buttons (preferred)</strong> — the server sends an inline approve/deny message to the operator&#39;s Telegram chat. Tapping &quot;Approve&quot; completes the login.</li><li><strong>Short-lived, single-use OTP</strong> — a numeric/alphanumeric code delivered via Telegram, verified via <code>POST /api/auth/verify-otp</code>. The OTP itself is never stored in plaintext; it is stored as an HMAC and compared constant-time.</li></ol><p>In tests, <code>AUTH_NOTIFICATION_ADAPTER=test</code> logs the notification (the approval prompt or OTP) to the console instead of sending it over Telegram, and is rejected by the live runtime.</p><h2 id="login-challenge-lifecycle" tabindex="-1">Login challenge lifecycle <a class="header-anchor" href="#login-challenge-lifecycle" aria-label="Permalink to &quot;Login challenge lifecycle&quot;">​</a></h2><p>A <code>LoginChallenge</code> record is created after the configured account check and tracks:</p><ul><li>a unique challenge <code>id</code></li><li>an <strong>expiry</strong> timestamp (short-lived)</li><li>a <strong>max attempts</strong> counter for OTP verification</li><li><strong>single-use</strong> semantics — once completed, consumed, or expired, it cannot be reused</li><li>a <strong>nonce</strong> bound to the challenge, used by the Telegram approval callback</li><li><strong>IP address and user-agent</strong> metadata captured at creation</li><li>a full audit trail (<code>AuditEvent</code>) for creation, each verification attempt, approval/denial, expiry, and completion</li></ul><p>Flow:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/auth/login          (username, plus password in password mode)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  account check OK? ──no──► rejected, rate-limited</span></span>
<span class="line"><span>        │yes</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  LoginChallenge created, notification sent (Telegram or dev log)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>GET /api/auth/challenge/{id}  (poll challenge status, e.g. from the web UI)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├── operator taps Approve/Deny in Telegram ──► POST /api/telegram/webhook</span></span>
<span class="line"><span>        │                                                 (validated by</span></span>
<span class="line"><span>        │                                                  TELEGRAM_WEBHOOK_SECRET,</span></span>
<span class="line"><span>        │                                                  callback nonce checked)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        └── or operator enters the OTP ──► POST /api/auth/verify-otp</span></span>
<span class="line"><span>                                                (challenge id + code)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>POST /api/auth/complete       (challenge id)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  Session created, cookie set, challenge marked consumed</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br></div></div><p>A challenge that expires, exceeds max attempts, or is denied cannot be completed; the operator must start a new login.</p><h2 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h2><ul><li>Sessions are <strong>server-side records</strong> (not pure JWTs) — a session can be revoked server-side at any time (logout, admin action, security incident) without waiting for expiry.</li><li>The session cookie is <code>HttpOnly</code>, <code>Secure</code> in live mode (forced by <code>APP_ENV=live</code>, see <code>.env.example</code>), and <code>SameSite=Strict</code>.</li><li>The session identifier <strong>rotates at login</strong> — a new session is always issued, never reused from a prior anonymous state.</li><li><code>SESSION_TTL_MINUTES</code> bounds session lifetime (default 720 = 12h); expiry is enforced server-side against the stored session record.</li></ul><h2 id="csrf" tabindex="-1">CSRF <a class="header-anchor" href="#csrf" aria-label="Permalink to &quot;CSRF&quot;">​</a></h2><p>State-changing requests (anything beyond a simple <code>GET</code>) require a CSRF token in addition to the session cookie. The token is issued alongside the session and must be echoed back on write requests; the cookie alone is not sufficient to mutate state, which limits classic CSRF against the cookie-based session.</p><h2 id="rate-limiting" tabindex="-1">Rate limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate limiting&quot;">​</a></h2><p>Rate limits apply independently to:</p><ul><li>login attempts (per account and per IP),</li><li>login-challenge creation,</li><li>OTP verification attempts (bounded by the challenge&#39;s own max-attempts counter as well),</li><li>Telegram callback processing (approve/deny nonce consumption).</li></ul><p>Limits are intentionally strict given the public-VPS threat model — see <a href="./security"><code>security.md</code></a>.</p><h2 id="recovery-codes" tabindex="-1">Recovery codes <a class="header-anchor" href="#recovery-codes" aria-label="Permalink to &quot;Recovery codes&quot;">​</a></h2><p>Recovery codes are the documented fallback when Telegram is unreachable (bot down, Telegram outage, lost phone, etc.):</p><ul><li>Generated at account setup, shown to the operator <strong>once</strong>.</li><li>Stored <strong>hashed</strong> (never in plaintext) in the database.</li><li>Each code is <strong>single-use</strong>; using one consumes it.</li><li>Every generation and use is audited (<code>AuditEvent</code>).</li><li>Controlled by <code>AUTH_RECOVERY_ENABLED</code> (default <code>true</code>) in <code>password</code> mode. Recovery is always unavailable in <code>telegram_only</code>, where Telegram is a hard dependency for login.</li></ul><h3 id="if-telegram-is-down" tabindex="-1">If Telegram is down <a class="header-anchor" href="#if-telegram-is-down" aria-label="Permalink to &quot;If Telegram is down&quot;">​</a></h3><p>These steps apply only in <code>password</code> mode. In <code>telegram_only</code>, recovery codes cannot bypass Telegram.</p><ol><li>Attempt the normal login (username + password) to create a login challenge as usual — this step doesn&#39;t depend on Telegram.</li><li>Instead of waiting for the Telegram approval/OTP, use <code>POST /api/auth/recovery</code> with a saved recovery code to complete authentication.</li><li>Each recovery code only works once — generate a fresh set (and store them somewhere safe, e.g. a password manager) after using one, since using your last code would otherwise leave you without an offline fallback.</li><li>If both Telegram and your recovery codes are unavailable, there is no API-level bypass by design; regaining access requires direct database access on the home application host.</li></ol><h2 id="sms" tabindex="-1">SMS <a class="header-anchor" href="#sms" aria-label="Permalink to &quot;SMS&quot;">​</a></h2><p>SMS as a second factor or recovery channel is <strong>explicitly deferred</strong> — not implemented, not planned for this milestone. Telegram (approval or OTP) plus recovery codes are the only supported paths.</p><h2 id="telegram-bot-commands" tabindex="-1">Telegram bot commands <a class="header-anchor" href="#telegram-bot-commands" aria-label="Permalink to &quot;Telegram bot commands&quot;">​</a></h2><p>The bot itself (see <a href="./mcp"><code>mcp.md</code></a> for the adjacent MCP surface) is validated by <code>TELEGRAM_ALLOWED_USER_ID</code> and <code>TELEGRAM_ALLOWED_CHAT_ID</code> — <strong>never by username</strong>, since usernames are not a stable or trustworthy identity in Telegram&#39;s API. The bot is a compact operations dashboard with progressive inline navigation. The home screen exposes only Incidents, Tasks, Luna and More; automation, MCP and the full status live under More. Callback navigation edits the current Telegram message when possible, with a new-message fallback when Telegram no longer permits editing. Callback queries are acknowledged immediately so Telegram does not leave a loading indicator active while a slower view is rendered. Supported commands:</p><ul><li><code>/start</code> or <code>/menu</code> — open the lightweight home screen.</li><li><code>/status</code> — full summary: providers, incidents, tasks, watcher, MCP and router state.</li><li><code>/tasks</code> — active task queue with per-task detail buttons.</li><li><code>/incidents</code> — open incidents with detail and &quot;already handled&quot; actions.</li><li><code>/watchers</code> — automation state and recent watcher runs.</li><li><code>/mcp</code> — MCP client roster and freshness.</li><li><code>/luna</code> — compatibility command for the fixed Operations overview shortcut.</li><li><code>/provider [claude|codex]</code> — switch the active Conversation Service <strong>model</strong> provider. This never touches infrastructure provider configuration (Proxmox, etc.) — see <a href="./providers"><code>providers.md</code></a> for that distinction.</li><li><code>/approve &lt;id&gt;</code> / <code>/deny &lt;id&gt;</code> — resolve a pending approval (login challenge or a high-risk tool approval), via a short-lived single-use callback nonce.</li></ul><p>Inline buttons use callback data such as <code>nav:tasks</code>, <code>task:detail:&lt;id&gt;</code>, <code>incident:detail:&lt;id&gt;</code>, <code>incident:handled:&lt;id&gt;</code>, <code>luna:summary</code> and <code>luna:triage</code>. Menus use compact, bounded lists and keep consequential actions, such as incident resolution, in the detail view. These callbacks only read control-plane state or call existing typed services. They do not expose arbitrary tool execution, shell, SSH, raw HTTP, or infrastructure write actions.</p><p>Ordinary Telegram text is tool-free chat. The <strong>Operations</strong> panel provides fixed overview/network/storage/security/automation/alert summaries plus a single-use <strong>Ask live question</strong> prompt. The latter is bound to the authorized user and chat, expires after five minutes and is consumed after one reply; it does not enable a sticky operational mode.</p><p>Telegram operational menus, inline actions, approval/task/Luna notifications, and controlled error messages use US English. Free-text Conversation Service replies remain Italian, and user content and historical records are not translated.</p>`,39)])])}const m=a(t,[["render",i]]);export{h as __pageData,m as default};
